static void ReadLineEvent()
{
    var line = new LabLine("L1");
    line.Changed += OnLine;
    line.Register(200);
}
static void OnLine(LabRegistrationEvent e)
{
    Console.WriteLine($"{e.LineId} {e.State} {e.SipStatus}");
}
// LabLine.Changed 的宣告是 Action<LabRegistrationEvent>，不是SDK事件。

